mapper.select:
SELECT u.id, u.employee_code, u.username, u.email, u.full_name, u.phone, u.avatar_url, u.department_id, u.org_node_id, u.keycloak_username, u.status, u.two_factor_enabled, u.last_login_at, u.created_at, COUNT(*) OVER() AS total_elements FROM iam.users u
JOIN iam.user_roles ur ON ur.user_id = u.id AND ur.is_deleted = FALSE JOIN iam.roles r ON r.id = ur.role_id AND r.is_deleted = FALSE
WHERE u.is_deleted = FALSE
AND u.status = #{status}
AND u.department_id = #{departmentId}
AND UPPER(r.code) = UPPER(#{roleCode})
AND ( LOWER(u.full_name) LIKE CONCAT('%', LOWER(#{query}), '%') OR LOWER(u.username) LIKE CONCAT('%', LOWER(#{query}), '%') OR LOWER(u.email) LIKE CONCAT('%', LOWER(#{query}), '%') )
ORDER BY
u.full_name ASC u.full_name DESC u.username ASC u.username DESC u.status ASC u.status DESC u.created_at ASC u.created_at DESC
, u.id ASC LIMIT #{limit} OFFSET #{offset}
